    z=((x-x0)+1j*g/2)/(s*np.sqrt(2)); prof=np.real(wofz(z))/(s*np.sqrt(2*np.pi)); return h*prof/np.real(wofz(1j*g/2/(s*np.sqrt(2))))/ (1/(s*np.sqrt(2*np.pi)))
